<?php require_once __DIR__.'/../../helpers/bootstrap.php'; require_login(); if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$pdo=db();try{$pdo->beginTransaction();$q=$pdo->prepare('SELECT * FROM products WHERE id=? FOR UPDATE');$q->execute([(int)$_POST['product_id']]);$p=$q->fetch();$qty=filter_var($_POST['quantity'],FILTER_VALIDATE_INT);$type=$_POST['type']==='OUT'?'OUT':'IN';if(!$p||!$qty||$qty<1||($type==='OUT'&&$qty>$p['stock']))throw new Exception('Data transaksi tidak valid atau stok tidak cukup.');$new=$type==='IN'?$p['stock']+$qty:$p['stock']-$qty;$pdo->prepare('UPDATE products SET stock=? WHERE id=?')->execute([$new,$p['id']]);$pdo->prepare('INSERT INTO stock_movements(product_id,user_id,type,quantity,note) VALUES (?,?,?,?,?)')->execute([$p['id'],$_SESSION['user']['id'],$type,$qty,trim($_POST['note']??'')]);$pdo->commit();flash('Transaksi stok berhasil.');redirect('../dashboard.php');}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$error=$e->getMessage();}}$products=db()->query('SELECT id,sku,name,stock FROM products ORDER BY name')->fetchAll();layout_start('Transaksi Stok');?><h1>Transaksi stok</h1><?php if(!empty($error)):?><div class="error"><?=e($error)?></div><?php endif?><form class="panel narrow" method="post"><input type="hidden" name="csrf" value="<?=csrf()?>"><label>Produk<select name="product_id" required><?php foreach($products as $p):?><option value="<?=$p['id']?>"><?=e($p['sku'].' · '.$p['name'].' (stok '.$p['stock'].')')?></option><?php endforeach?></select></label><label>Tipe<select name="type"><option value="IN">Barang masuk</option><option value="OUT">Barang keluar</option></select></label><label>Quantity<input type="number" min="1" name="quantity" required></label><label>Catatan<input name="note"></label><button>Simpan transaksi</button></form><?php layout_end();
